insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 1, 'The published well carries two casing strings. How many segments does the exposed profile have?', '["Three: the two production casing weights above the liner top, and the liner below it.", "Two, one for each string in the program.", "Four, because the overlap between the two strings is treated as its own segment with a bore taken from both of them.", "One, because the profile reports the smallest bore anywhere in the well and applies it over the whole depth range."]'::jsonb, 0, 'The casing changes weight at sixteen hundred and fifty metres and the liner takes over at twenty four hundred.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 2, 'Below the liner top, what has happened to the nine and five eighths inch casing?', '["It has been pulled and recovered before the liner was run.", "It has been milled out over the overlap so that the liner can be hung inside it without reducing the available bore.", "Nothing; it is still there, and simply is not the innermost bore any more.", "It ends at the liner top, which is why the liner was set at that depth rather than at any other in the first place."]'::jsonb, 2, 'The profile is a record of what is innermost, not a record of what exists.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 3, 'Why does each profile row carry a label naming its string?', '["Because the label is needed to look up the drift deduction.", "Because when a check fails the first question is which string caused it.", "Because two rows with the same bore would otherwise be merged, and the merge has to be prevented where the strings differ.", "Because the label records which section of the casing program the row came from, for traceability in the design document."]'::jsonb, 1, 'A number without a label sends the reader back to the program to redo the calculation that just ran.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 4, 'State the rule that resolves overlapping strings.', '["The most recently run string always wins.", "The strings are combined by taking the average of their bores, weighted by the length over which each of them is present.", "A liner always takes precedence over casing, and casing always takes precedence over any conductor or surface string above.", "At any depth, the exposed bore is the smallest inside diameter among the strings present."]'::jsonb, 3, 'Innermost and smallest are the same statement in this geometry, and the engine implements it as the smallest.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 5, 'A component is run to a depth below the liner top and checked against the production casing bore instead of the liner. What is the error?', '["The answer is far too generous, by the difference between the two bores.", "The answer is too conservative but still usable.", "There is no error, because the production casing is present at that depth as well and either bore is a legitimate choice.", "The error affects only the volume calculation, since the clearance check reads the drift rather than the nominal bore."]'::jsonb, 0, 'In the published well that difference is enough to turn a failing packer into a passing one.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 6, 'Where in the published well is the single most consequential depth for the clearance module?', '["The hanger, where the string is landed.", "The change of casing weight at sixteen hundred and fifty metres, which is the only other place the bore changes at all.", "The liner top, where the exposed bore steps down by about a quarter.", "The packer setting depth, because that is where the tightest component in the published string happens to land."]'::jsonb, 2, 'Two physically similar components get completely different verdicts because one is above it and one below.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 7, 'What triggers a cut in the profile?', '["A fixed depth step chosen by the caller.", "A section boundary within a string, or the top or bottom of an inner string.", "Any depth at which a component of the completion string begins or ends, so that the two sets of breakpoints stay aligned.", "Every hundred metres, which is the resolution at which casing programs are normally recorded and reported."]'::jsonb, 1, 'There is no resampling, because a clearance reported at a resampled depth would be reported at a fiction.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 8, 'Why does the merge test the label as well as the bore?', '["Because two strings never have the same bore.", "Because the label carries the drift deduction class, which differs between strings even where their bores coincide.", "Because merging is only permitted within a string, and the label is what identifies which string a section belongs to.", "Because a failed check reports the label, and merging across strings would make the report ambiguous."]'::jsonb, 3, 'Two different strings that happen to share a bore stay as two rows, deliberately.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 9, 'A program consists only of a liner from twenty four hundred metres down. What is the governing drift at two thousand eight hundred?', '["Nothing, because the program says nothing about what is above the liner.", "The liner drift, since the liner is present at that depth.", "Zero, which is the conservative answer and correctly stops anything from being reported as passing through an unknown interval.", "The drift of the shallowest string in the program, applied over the whole depth range down to the point of interest."]'::jsonb, 0, 'The naive answer is wrong whenever anything above the liner is tighter, which is the normal case.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 10, 'Define the governing drift to a depth.', '["The drift of the profile segment at that depth.", "The smallest drift of any profile segment at or above that depth.", "The smallest drift anywhere in the well, including below the depth in question, since the string will eventually pass all of it.", "The average of the drifts of every segment above the depth, weighted by the length over which each of them applies."]'::jsonb, 1, 'The constraint on a component is a property of the path, not of the destination.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 11, 'What property does the governing drift have as a function of depth?', '["It is non decreasing with depth.", "It varies with depth according to the casing program and has no general monotonic property that can be relied upon.", "It is non increasing, so it can only step down.", "It is constant within a string and steps up at each liner top, reflecting the smaller bore of the string that ended above."]'::jsonb, 2, 'A curve that stepped up would mean a restriction had been un passed, which cannot happen.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 12, 'How many distinct governing drift values does the published well have, and where do they step?', '["Two values, stepping at the liner top only.", "Four values, because the liner is run in two sections of different weight below the top of the overlap with the casing.", "Three values, stepping at the packer depth and at total depth, which are the only depths the completion actually cares about.", "Three values, stepping at sixteen hundred and fifty metres and at the liner top."]'::jsonb, 3, 'The second step is the one that matters, taking a quarter off the available bore.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 13, 'The governing drift function returns a label. Which segment does that label come from?', '["The segment that set the minimum, which may be far above the depth asked about.", "The segment present at the depth asked about.", "The segment immediately above the depth asked about, which is the last one the component passed before reaching it.", "The shallowest segment in the whole profile, since every component has to pass that one before reaching any other."]'::jsonb, 0, 'Those differ everywhere below a restriction, and naming the setting segment is what points at the problem.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 14, 'A volume calculation and a clearance check both meet the same gap in the casing program. What do they each do?', '["Both refuse the calculation entirely.", "The volume skips and warns; the clearance returns nothing.", "The volume returns zero for the interval and the clearance uses the nearest bore above it, which is the best estimate available.", "Both skip the interval and continue, since a gap affects only the interval in which it occurs and nothing above or below it."]'::jsonb, 1, 'A volume is additive and a verdict is not, so the same missing data is recoverable for one and fatal for the other.'),
  ('completion', 'intermediate', 'module', 'm01-the-exposed-program', 15, 'Why is a resampled profile a worse object than a cut and merged one?', '["Because it takes longer to compute.", "Because the resampling interval would have to be chosen, and no physical consideration determines what it should be.", "Because it introduces depths no string has, and reports results at them.", "Because a resampled profile cannot be merged, so the row count grows and a reader cannot see where the real changes are."]'::jsonb, 2, 'Cutting only where things change makes a change in the profile mean a real change in the well.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 1, 'Write down the run in clearance of a component.', '["The casing bore at its depth, less its inside diameter.", "The governing drift to its bottom depth, less its outside diameter.", "The governing drift to its bottom depth, less its outside diameter, divided by two to give the gap on either side.", "The smallest casing bore anywhere in the well, less the largest outside diameter found anywhere in the completion string."]'::jsonb, 1, 'Positive means it goes and negative means it does not.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 2, 'The reported clearance is diametral. What is the gap on each side if the component is centred?', '["Half of it.", "The same as the reported value.", "Twice the reported value, since the gap appears on both sides of the component and the two must be added together.", "It cannot be found, because the reported value is an area difference rather than a difference of two diameters."]'::jsonb, 0, 'A component with five millimetres of clearance has two and a half on each side if centred, and none on one side if not.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 3, 'Which of these does a run in clearance NOT account for?', '["The outside diameter of the component.", "The tightest casing bore between surface and the depth at which the component finally comes to rest in the string.", "The extra room a rigid component needs to pass through a dogleg.", "The API drift deduction applied to the casing rows that the component has to pass on the way down to that depth."]'::jsonb, 2, 'There is no survey in this calculation, so there is no curvature in it either.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 4, 'In the published string, how wide is the spread between the loosest and the tightest clearance?', '["Less than two to one.", "About five to one, which is roughly the ratio between the production casing bore and the liner bore in the same well.", "They are within a few percent of each other, because every component in the string is sized to the same tubing.", "More than twenty to one."]'::jsonb, 3, 'Clearance is not roughly the same everywhere with one or two exceptions.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 5, 'The safety valve and the side pocket mandrel in the published string share an outside diameter. Why do their clearances differ so much?', '["Because one stops above the liner top and the other stops below it.", "Because their inside diameters differ.", "Because the side pocket mandrel is eccentric, so its effective diameter for clearance purposes is larger than its nominal one.", "Because the safety valve is checked against the nominal casing bore and the mandrel against the drift of the same casing."]'::jsonb, 0, 'Nothing about the components explains it. The difference is entirely in where they stop.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 6, 'Why would checking the safety valve against the liner be wrong?', '["Because the liner drift is larger than the casing drift.", "Because the valve stops far above the liner and never encounters it.", "Because the valve is run on a separate trip from the rest of the string, so it never passes any of the casing below it.", "Because the liner is not part of the exposed profile at the depth where the valve is checked, only below the liner top."]'::jsonb, 1, 'The answer would be wrong in the conservative direction, which is still wrong.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 7, 'Move a component deeper in a well. What can happen to its clearance?', '["It can only get looser or stay the same.", "It can move in either direction, depending on whether the casing at the new depth is heavier or lighter than at the old one.", "It can only get tighter or stay the same.", "It stays the same, because the clearance depends on the component and the casing program rather than on the depth."]'::jsonb, 2, 'That monotonicity comes straight from the governing drift being a running minimum.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 8, 'State the three clearance verdicts and their conditions.', '["Fail below zero and pass above it, with no third verdict.", "Fail below the margin, warn between the margin and twice the margin, and pass above twice the margin for any component.", "Fail below zero, warn where the clearance cannot be computed because the profile has a gap, and pass everywhere else.", "Fail below zero, warn between zero and the margin, pass above the margin."]'::jsonb, 3, 'The middle one is where the engineering conversation happens.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 9, 'Why does the clearance check need a margin at all?', '["Because the drift describes new pipe and the well contains scale, ovality and damage.", "Because the outside diameters of the equipment are approximate.", "Because the drift is a statistical figure with a stated confidence, and the margin converts it to a deterministic limit.", "Because the component may be run eccentrically, so half of the diametral clearance is unavailable on one side of the hole."]'::jsonb, 0, 'A clearance of half a millimetre against a guarantee is very likely negative in the ground.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 10, 'Why is the clearance margin absolute rather than proportional?', '["Because absolute margins are easier to compute.", "Because the things it protects against are absolute: a millimetre of scale is a millimetre.", "Because a proportional margin would have to be recomputed each time the casing weight changed, which the engine avoids.", "Because the specification defines the drift deduction as an absolute value, and the margin has to be dimensionally consistent."]'::jsonb, 1, 'A proportional margin would be too tight on small casing and too generous on large.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 11, 'The tightest row in the published string is the production packer. Why is a packer usually the tight one?', '["Because packers are the longest components in a string.", "Because the packer body has to house a setting mechanism, which makes it wider than any other item in the completion kit.", "It is sized to the casing it seals in, and it usually sits below the liner top.", "Because the packer is the last component run, so any accumulated depth error in the tally is concentrated at its depth."]'::jsonb, 2, 'A packer that cleared the liner easily would not seal in it.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 12, 'Which two levers are available when a packer clearance is too tight, and what does each cost?', '["Increase the warn margin, or ream the liner.", "Change the tubing size, or run the packer on a separate trip so that it does not have to pass the rest of the string first.", "Accept the clearance, or drift the liner first, since a drift run frequently shows more room than the catalog value implies.", "Move it above the liner top, losing the seal position, or fit a slimmer packer, usually losing rating."]'::jsonb, 3, 'The well takes the tight clearance because the alternatives are worse.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 13, 'An oversized safety valve is run to two thousand five hundred metres in the published well and then to two thousand. What happens?', '["It fails at the deeper depth and passes at the shallower one.", "It fails at both depths.", "It passes at both, because the governing drift at both depths is set by the production casing rather than by the liner below.", "It fails at the shallower depth and passes at the deeper one, because the liner drift is larger than the casing drift is."]'::jsonb, 0, 'The component was identical in both runs. Only the depth changed, and the verdict flipped.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 14, 'When an oversized component fails, what does the engine name alongside the row?', '["The depth at which the component was placed.", "The governing drift and the label of the string that set it.", "The nearest standard component of the same type that would have passed, so that a substitution can be made immediately.", "The amount by which the warn margin would have to be reduced for the component to be reported as passing instead."]'::jsonb, 1, 'Naming the string points at the liner top, which is where the problem is, rather than at the component depth.'),
  ('completion', 'intermediate', 'module', 'm02-getting-it-down', 15, 'In a two row string with one pass and one fail, which row is the worst?', '["The row with the smaller clearance, whichever it is.", "The row with the largest outside diameter, since that is the component that will need to be changed if the design is revised.", "The failure, because a fail outranks a pass whatever the clearances are.", "Neither, because a worst row is only meaningful when every row in the string shares the same verdict as the others."]'::jsonb, 2, 'That is the easy case. The hard case is a string where every row passes.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 1, 'What question does the through bore answer?', '["What can be run inside the completion once it is in the hole.", "Whether the completion string will go into the well.", "How much fluid the completion holds, which is what has to be displaced when the tubing is changed over to packer fluid.", "Which casing string sets the tightest constraint on the components as they are run to their setting depths in the well."]'::jsonb, 0, 'It is inside diameters against each other, not outside diameters against a casing bore.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 2, 'Which of these operations is limited by the through bore?', '["Setting the packer with a hydraulic setting tool.", "Cementing the liner in place before the completion string is made up and run into the well on the production tubing.", "Running a memory gauge on wireline to a depth below the safety valve.", "Circulating the annulus above the packer to packer fluid before the packer is set and the well is put on production."]'::jsonb, 2, 'Almost everything that happens to a well after completion goes through the tubing.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 3, 'How is the through bore computed?', '["As the average inside diameter weighted by length.", "As a running minimum of the component inside diameters, taken from the top down.", "As the smallest inside diameter below the packer, since a tool only needs to reach the producing interval at the bottom.", "As the smallest inside diameter of the equipment items, excluding the plain tubing which is never the controlling bore."]'::jsonb, 1, 'The headline is the last value; the intermediate values are what a tool can reach.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 4, 'The published string is almost entirely pipe of two point nine nine two inch bore. What is it advertised at?', '["Two point nine nine two inches, the tubing bore.", "Two point seven five inches, which is the bore of the safety valve and the largest restriction over most of the string.", "Two point four four one inches, which is the bore of the coupling rather than the pipe body of the tubing itself.", "Two point six three five inches, because of one component less than half a metre long."]'::jsonb, 3, 'The number a completion is advertised with comes from the smallest nipple in it.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 5, 'Why can the running minimum only step down?', '["Because a tool cannot un pass a restriction it has already been through.", "Because the components get smaller with depth.", "Because the bores are sorted into decreasing order before the running minimum is taken over the resulting sequence.", "Because the tubing bore is the largest in the string, so every later component can only be equal to it or smaller."]'::jsonb, 0, 'The same argument as the governing drift in the clearance check, in the other direction.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 6, 'What does the running form of the through bore tell you that the headline does not?', '["Which component has the smallest outside diameter.", "How much fluid can be circulated through the string at a given rate, since the bore sets the friction along the flow path.", "What can reach any depth, rather than only what can reach the bottom.", "Whether the restriction is a machined profile or an incidental consequence of a component that had to be that size."]'::jsonb, 2, 'A gauge that will not pass the no go nipple can still be set anywhere above it.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 7, 'In the published string, at how many of the thirteen components does the cumulative minimum equal the component''s own bore?', '["All thirteen.", "One, since only the component with the smallest bore in the string can equal the running minimum at its own position.", "Seven, which is the number of components in the string whose bore is smaller than the plain tubing bore above them.", "Three."]'::jsonb, 3, 'Ten of the thirteen have bores that never limit anything at all.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 8, 'Which component sets the through bore over most of the published string?', '["The XN no go nipple, whose bore is the smallest.", "The safety valve, whose bore is two point seven five inches.", "The production packer, whose bore is the same as the safety valve and which sits far deeper in the same string.", "The sliding sleeve, which is the only other component in the string with a bore below the plain tubing bore above it."]'::jsonb, 1, 'It is the restriction over about two thousand four hundred and fifty metres.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 9, 'Over how much of the published string is the no go nipple the restriction?', '["Less than four metres.", "About half the string.", "About two thousand four hundred and fifty metres, which is the same extent as the safety valve above it in the string.", "About one hundred and fifty metres, which is the length of the tubing run above the safety valve near the top of the well."]'::jsonb, 0, 'The completion is advertised at the no go value, which governs about a tenth of a percent of the string.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 10, 'One of the two restrictions in the published string is a cost and the other is a feature. Which is which?', '["Both are side effects of the components that cause them.", "The valve restriction is deliberate, because a restricted bore is what allows the flapper to seal, and the no go is incidental.", "The valve restriction is a side effect; the no go restriction is the point of the component.", "Both are deliberate, since every restriction in a completion is chosen by the designer against a list of intended tool sizes."]'::jsonb, 2, 'The arithmetic treats them identically, and the design options for the two are completely different.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 11, 'A client needs a larger tool through the published string. Which restriction can be attacked?', '["The no go nipple, by machining its bore larger.", "Neither, because both restrictions are set by components that are required by regulation to be present in the string.", "The tubing, by running a larger size, which raises every bore in the string including the two restrictions above.", "The safety valve, by fitting a larger bore valve at a larger outside diameter."]'::jsonb, 3, 'That is a genuine trade between the two checks in this tier, because the wider body has to clear the casing.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 12, 'What is the difference between an extreme and an extent?', '["An extreme is how small; an extent is how much of the string it governs.", "An extreme is a maximum and an extent is a minimum.", "An extreme is computed over the string and an extent is computed over the casing program that the string is run inside.", "An extreme is reported by the engine and an extent is a field measurement, which is why the two rarely agree in practice."]'::jsonb, 0, 'A running minimum gives the first for free and gives the second only if you go looking.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 13, 'How do you compute the extent of each restriction?', '["Divide the string length by the number of restrictions.", "Walk the running minimum and attribute each component''s length to whichever restriction is current.", "Subtract the depth of each restriction from the depth of the next one below it, which gives the interval each one governs.", "Integrate the difference between each component bore and the running minimum over the length of the string, then normalise."]'::jsonb, 1, 'A handful of lines of code, no new inputs, and a single misleading number becomes a description.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 14, 'When is the headline through bore the right summary on its own?', '["Never; it should always be reported with its extent.", "When every component in the string has the same bore, in which case the extreme and the extent describe the same fact.", "When the operation has to reach the bottom, where the extreme is the binding constraint.", "When the restriction governs more than half the string, so that quoting it alone is representative of the whole of it."]'::jsonb, 2, 'A plug set in the no go nipple has to pass the no go nipple, whatever the rest of the string looks like.'),
  ('completion', 'intermediate', 'module', 'm03-getting-through-it-afterwards', 15, 'The through bore rules a tool out with certainty. What does it rule in?', '["Any tool smaller than the reported value.", "Any tool smaller than the reported value that is shorter than the drift mandrel length used for the tubing in the string.", "Any tool smaller than the reported value, provided the well is vertical over the interval the tool has to travel through.", "Nothing; length, deviation and fluid can all still stop a tool that fits."]'::jsonb, 3, 'It is a useful thing for a calculation to do, provided the reader knows which of the two it is doing.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 1, 'Which two of the four volumes require the exposed casing profile?', '["The capacity and the displacement of the string.", "The annulus above the packer and the volume below the packer.", "The capacity and the annulus above the packer, since both are integrated over the length of the string above the seal.", "The displacement and the volume below the packer, both of which describe fluid outside the string rather than inside it."]'::jsonb, 1, 'The first two are properties of the string alone and would not change in a different well.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 2, 'In the published well, how does the annulus above the packer compare with the string capacity?', '["It is more than five times as large.", "It is about the same size.", "It is about twice as large, which is also the ratio between the string displacement and the string capacity in that well.", "It is smaller, because the annular gap between the tubing and the casing is narrow compared with the tubing bore itself."]'::jsonb, 0, 'Area goes as the square, and the casing bore is much larger than the tubing outside diameter.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 3, 'Why is the annulus so much larger than people expect?', '["Because the annulus includes the volume inside the string.", "Because the annulus is integrated to total depth rather than to the packer, which adds the whole of the liner section to it.", "Because the annular area is several times the tubing bore area, and it runs for kilometres.", "Because the casing bore used is the nominal one rather than the drift, which overstates the area by a few percent throughout."]'::jsonb, 2, 'Over two and a half kilometres that adds up to a lot of packer fluid, and packer fluid is not free.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 4, 'The annulus integral has breakpoints from two independent sources. What are they?', '["The packer depth and the total depth of the well.", "The depths at which the string changes size and the depths at which the annular fluid changes density along the well.", "The liner top and the change of casing weight, which are the only two depths at which the exposed bore actually changes.", "The casing section boundaries and the component boundaries of the string."]'::jsonb, 3, 'Merge the two sets, sort them, and both areas are constant between consecutive breakpoints.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 5, 'Does the annulus calculation account for the extra width of a safety valve body?', '["Yes; the string outside area at each depth is the local component''s, not the tubing''s.", "No; it uses the tubing outside diameter throughout.", "Only if the component is longer than the resolution of the integration, which is set by the shortest casing section present.", "Only above the packer, since below the packer the calculation uses the full casing bore and ignores the string entirely."]'::jsonb, 0, 'A five and three quarter inch valve displaces more annulus than the tubing around it, over its own length.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 6, 'Why is the volume below the packer computed on the full casing bore?', '["Because the tail of the string is too short to matter.", "Because the tail is open and perforated, so the fluid inside and around it is one body.", "Because the outside diameter of the perforated joint is not published, so the annular area below the packer cannot be found.", "Because a gross volume is always the conservative choice, and conservatism is appropriate below the packer in particular."]'::jsonb, 1, 'Treating it as an annulus would exclude a volume that nothing physical excludes.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 7, 'For which calculation is the gross below packer volume the right number?', '["A coiled tubing cleanout design.", "A circulation rate calculation, where the fluid follows a path down one area and back up another rather than filling a space.", "A kill sheet, where the fluid has to fill everything below the packer.", "A pit gain calculation while running the completion in, since the tail is the first part of the string to enter the well."]'::jsonb, 2, 'A circulation path uses two areas rather than one, and this engine does not compute paths.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 8, 'The engine states the packer and total depth condition as two separate refusals. Why?', '["Because the two conditions are not equivalent.", "Because one of the two is a hard refusal and the other only produces a warning, depending on which value is out of range.", "Because the packer depth is entered by the completion engineer and the total depth by the driller, so both must be validated.", "Because the two errors come from different places and naming one saves checking both."]'::jsonb, 3, 'A mistyped packer depth and a mistyped total depth are different mistakes with the same symptom.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 9, 'Why is the volume integrand piecewise constant?', '["Because both the casing area and the string area are step functions of depth.", "Because the fluid density is constant with depth.", "Because the integration is performed on a fixed grid, which forces the integrand to take a single value in each interval.", "Because the string is made up of joints of equal length, so the area repeats at a regular interval along the whole string."]'::jsonb, 0, 'So the exact answer is a finite sum of products, with no discretisation error in it at all.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 10, 'What is the larger problem with slicing the well into fixed intervals for the volume?', '["It is slower than the exact method.", "The answer depends on the slice size, which has no physical meaning.", "It cannot handle a gap in the casing program, because a slice that straddles the gap has no single bore to be evaluated at.", "It systematically overstates the volume, because the areas within each slice are evaluated at the top of that slice."]'::jsonb, 1, 'An answer that depends on a numerical parameter with no physical meaning is an answer that cannot be checked.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 11, 'Under what circumstance would quadrature be the right tool for this integral?', '["If the string had more than fifty components.", "If the well were deviated, since the areas normal to the hole axis then vary continuously with the inclination along it.", "If either area varied continuously with depth, as with a caliper log of an open hole.", "If the packer depth fell between two casing section boundaries rather than exactly on one of them in the program."]'::jsonb, 2, 'None of those inputs is in this model, so none of that machinery is here.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 12, 'What does the engine do when the profile does not cover an interval it is integrating?', '["It refuses the calculation and returns nothing.", "It uses the bore of the nearest covered interval, which keeps the volume complete at the cost of a small unquantified error.", "It returns the volume computed over the covered intervals only, with no indication that anything at all has been left out.", "It skips the interval, continues, and adds a warning naming the depths."]'::jsonb, 3, 'The number that comes back is real and incomplete, and the warning is the only thing that says so.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 13, 'Why can a volume tolerate a gap when a clearance verdict cannot?', '["Because a volume is additive and a verdict is not.", "Because volumes are less important than verdicts.", "Because the volume integral is performed after the profile is built, so it can inspect the gap and decide what to do about it.", "Because a clearance check reads the drift and a volume reads the nominal bore, and only the drift is unavailable in a gap."]'::jsonb, 0, 'A pass over the intervals we know about is a wrong answer, because the missing interval could contain the restriction.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 14, 'The warning list comes back empty. What does that establish?', '["That the casing program contains no errors.", "That the profile covered every interval, so the volume is complete.", "That the volume has been verified against the independent oracle, which is what the empty warning list is reporting.", "That no component in the string extends beyond the depth range covered by the casing program that it is run inside."]'::jsonb, 1, 'Warnings catch missing data. They do not catch incorrect data, and nothing here does.'),
  ('completion', 'intermediate', 'module', 'm04-the-volumes', 15, 'A casing program has a typo in one bore. What does the volume calculation report?', '["A warning naming the affected interval.", "A refusal, because the bore would fail the internal consistency check between the outside diameter and the wall thickness.", "A complete volume, no warnings, and a wrong answer.", "A volume with an estimated uncertainty, since the engine compares each bore against the catalog for that size and weight."]'::jsonb, 2, 'That is the limit of what a warning system can do, and it is worth knowing where the limit is.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 1, 'What was the engine reporting as the worst clearance row on the published completion?', '["The production packer, which is correct.", "The side pocket mandrel, which is the second tightest row and therefore a plausible but incorrect selection to have made.", "The first tubing joint, at a clearance more than twenty times the real tightest one.", "Nothing at all, because the reduction returned an undefined result whenever every row in the string shared one status."]'::jsonb, 2, 'A summary saying the string had plenty of room, on a string whose margin was under two millimetres.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 2, 'What was the cause of the defect?', '["The ranking was by status alone, so no row ever outranked the incumbent on a uniform string.", "The clearance values themselves were computed wrongly.", "The rows were sorted by depth rather than by clearance, so the reduction returned whichever row happened to be shallowest.", "The governing drift was taken at each component''s own depth rather than as a running minimum from surface downward."]'::jsonb, 0, 'The reduction then returned whatever it started with, which is the first row.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 3, 'Which strings did the defect affect?', '["Only strings containing at least one failing row.", "Every string in which all rows shared a status, which is every string that passes.", "Only strings run into a liner, since that is the geometry in which the tightest row is not also the first row in the tally.", "Only strings with more than ten components, because the reduction was correct for short strings and degenerated for long ones."]'::jsonb, 1, 'So it was invisible where somebody was looking for a problem and present where the report was reassurance.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 4, 'Why does that condition make the defect more dangerous rather than less?', '["Because passing strings are more numerous than failing ones.", "Because a failing string would be investigated anyway, whereas a passing string is normally reported without further checking.", "Because the error grows with the number of rows, and a passing string usually has more components than a failing one does.", "Because a finished design passes everywhere, and that is exactly when the summary is read as reassurance."]'::jsonb, 3, 'A reader who trusted it would have concluded the design had slack it did not have.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 5, 'The engine had a golden file and an independent oracle. Why did they not catch this?', '["The oracle used the same ranking code as the engine.", "The golden file carried a worst row but it had been generated from the engine output rather than from the oracle output.", "The oracle never computed a worst row, so the golden had no field to compare against.", "The oracle was written for a failing string, on which the reduction happens to give the correct answer anyway."]'::jsonb, 2, 'It was an output of the engine that no test read.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 6, 'Why does verifying every row not verify the worst row?', '["Because the rows are data and the selection is logic, and correct data can be reduced wrongly.", "Because the rows were not in fact all verified.", "Because the worst row is reported with a different set of fields from the rows, so the comparison would not have matched.", "Because the selection is made before the rows are computed, so the rows that were verified are not the ones it chose from."]'::jsonb, 0, 'It feels covered, and that feeling is the trap.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 7, 'Which kind of output has the same risk profile as a worst row?', '["Any output expressed in derived units.", "Any summary of other outputs: a controlling item, a binding constraint, a recommended value.", "Any output that depends on more than one input, since the interaction between inputs is what tests most often fail to cover.", "Any output computed by a reduction over an array, whether or not that reduction is reported to the user of the tool."]'::jsonb, 1, 'The detailed outputs get compared because they are the substance. The summary gets read by everyone and tested by nobody.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 8, 'What rule follows for an independent oracle?', '["It has to be written in a different language.", "It has to be written by a different engineer from the one who wrote the engine, so that the two cannot share an assumption.", "It has to reproduce the engine to the last bit, rather than to a tolerance, so that a selection difference would show up.", "It has to compute every output the engine reports, including the convenience ones."]'::jsonb, 3, 'If the oracle skips an output, that output is unverified however thorough the rest of the comparison is.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 9, 'State the corrected ranking rule.', '["Rank by status first, then by the tightest clearance within that status.", "Rank by clearance alone, ignoring the status.", "Rank by status first and then by depth, so that the deepest row of the most severe status is the one that gets reported.", "Rank by the ratio of the clearance to the warn margin, which normalises the comparison across strings with different margins."]'::jsonb, 0, 'That gives the right answer in both regimes, mixed and uniform.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 10, 'What does the corrected ranking do with two rows of equal status and equal clearance?', '["It reports both as joint worst.", "It keeps the first, which makes the result deterministic.", "It selects the one with the larger outside diameter, on the grounds that the wider body is the one more likely to be changed.", "It selects the deeper of the two, since a tight row deeper in the string is harder to remedy than a shallow one."]'::jsonb, 1, 'Determinism matters for a value that goes into a report and gets compared between runs.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 11, 'What does the corrected ranking do with a row whose clearance could not be computed?', '["It always selects it, since an unknown is the worst case.", "It treats the missing value as zero, which places the row between the failing rows and the ones that pass with margin.", "It never selects it over a row that has a clearance value.", "It excludes the whole string from the check, because a single unevaluated row makes the selection meaningless anyway."]'::jsonb, 2, 'A row we could not evaluate is not evidence of tightness.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 12, 'Which assertion in the guard would fail loudly if the reduction degenerated again?', '["That the selected row has a positive clearance.", "That the number of rows returned equals the number of components in the string, which a degenerate reduction would change.", "That the selected row''s status matches the most severe status present anywhere in the list of rows for that string.", "That the ratio between the first row and the selected one exceeds twenty on the published string."]'::jsonb, 3, 'A degenerate selection on that string gives exactly that ratio, so the assertion is aimed at the failure mode.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 13, 'How should the phrase worst row be read now?', '["As the tightest row within the most severe status present.", "As the row with the largest outside diameter.", "As the row most likely to cause a problem during running, taking both the clearance and the component length into account.", "As the row whose clearance is closest to zero, whether that clearance is positive or negative on the string in question."]'::jsonb, 0, 'It is a precise statement, and the phrase was doing two jobs before.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 14, 'What habit does this module recommend for any tool?', '["Never rely on any summary output at all.", "Check a reported single worst case against the full list once by hand.", "Rerun every calculation twice with different inputs, so that a summary that does not move can be identified as suspect.", "Require that every summary output be reported together with the full list that it was derived from, in every report."]'::jsonb, 1, 'If the two agree you have learned what the tool means by worst, which is not always what you meant.'),
  ('completion', 'intermediate', 'module', 'm05-reading-a-check-critically', 15, 'Which of these is NOT covered by the Professional tier?', '["Whether every component clears the casing above it.", "What can be run through the finished string, where the restrictions are, and how much of the string each one governs.", "Whether the string can be pushed to depth in a deviated hole.", "How much packer fluid the annulus above the packer takes, given a casing program to integrate the string against."]'::jsonb, 2, 'Running mechanics needs a survey and a friction factor, and neither is in this model.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'A hiring manager asks what a Professional pass in this course demonstrates. What is the accurate reply?', '["That you can design and specify a completion for any well.", "That you can build a profile, run both fit checks with margins, and integrate the four volumes.", "That you can compute the thermal and pressure length changes of a tubing string and size a seal arrangement against them.", "That you can select equipment from vendor catalogs and confirm that it is correctly rated for the service the well will see."]'::jsonb, 1, 'And that you can read a tool''s summary critically enough to check it against its own detail.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'One idea runs through the whole tier. Which is it?', '["Both fit questions are about a path rather than a point.", "Every depth in the course is a measured depth.", "The exposed profile takes the innermost bore wherever two strings overlap, which resolves the whole casing program at once.", "The four volumes are computed by exact summation over merged breakpoints rather than by numerical quadrature on a grid."]'::jsonb, 0, 'Getting down depends on everything above the destination; getting through depends on everything above the target.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'A report shows thirteen green clearance rows and a summary calling the string comfortable. What do you do?', '["Accept the report, since every row passed.", "Ask for the warn margin to be raised until something warns, which is the only way to see how much slack the design has.", "Ask for the tightest row and its margin, because the tightest row is the design.", "Ask for the volumes as well, since a clearance report on its own does not establish that the completion is a workable design."]'::jsonb, 2, 'Everything else on the sheet is passing comfortably and contributes nothing to the decision.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'A colleague proposes placing a side pocket mandrel a hundred metres above a liner top instead of below it. What is the trade?', '["No trade; the clearance is unchanged by the move.", "A smaller clearance, because the casing above a liner top is always tighter than the liner itself over the overlap interval.", "A larger clearance and a smaller through bore, since the mandrel bore then becomes the controlling restriction from that depth.", "A much larger clearance, against a gas lift injection point higher in the string than intended."]'::jsonb, 3, 'That trade is real and it is made on wells.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'A component is described as having a clearance of four millimetres against a warn margin of three. How do you read it?', '["It warns, because four is close to three.", "It passes, by one millimetre, against a guarantee that describes new pipe.", "It fails, because a clearance smaller than twice the warn margin is not considered acceptable on any completion design.", "It passes comfortably, because the margin has already accounted for everything that could make the real bore smaller."]'::jsonb, 1, 'Zero clearance against a guarantee is not zero clearance in a well.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'A completion is advertised at a bore of two point six three five inches. What is the first thing to ask?', '["Over how much of the string that restriction actually applies.", "Which vendor supplied the component that sets it.", "Whether the figure is a drift or a nominal bore, since for a machined profile the two would be quite different numbers.", "What the outside diameter of the controlling component is, so that its clearance against the casing can also be checked."]'::jsonb, 0, 'When a summary is a minimum, ask over how much.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'You are handed a casing program with a section missing between two others. What should the tooling do?', '["Fill the gap with the bore of the section above it.", "Refuse both calculations, since neither can be relied upon when the program describing the well is known to be incomplete.", "Warn and skip for the volume, and return nothing for the governing drift.", "Compute both over the covered intervals and report them as complete, since the gap is normally a section that was not entered."]'::jsonb, 2, 'A volume is additive and a verdict is not, so the same missing data is recoverable for one and fatal for the other.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'Two tools disagree about the annulus volume by three percent. What would you check first?', '["Whether one of them used the wrong fluid density.", "Whether one of them integrated to total depth rather than to the packer, which would explain a much larger discrepancy.", "Whether one of them used the drift rather than the nominal bore, which would understate the annular area throughout.", "Whether one of them sliced the well on a fixed grid rather than cutting on breakpoints."]'::jsonb, 3, 'A gridded answer moves when the grid moves, for no physical reason.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'An engineer wants to add a dogleg allowance to the clearance check. What has to arrive first?', '["A friction factor for the casing.", "A survey, from which the curvature at each component depth can be found.", "A component stiffness for each item in the catalog, since the extra clearance needed depends on how much the body can flex.", "A revised drift specification, because the standard mandrel test does not describe passage through a curved section at all."]'::jsonb, 1, 'Every absent item needs an input the model does not carry.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'A report names the liner as the controlling string for a component that sits five hundred metres below the liner top. Is that right?', '["Yes, if the liner is the tightest thing anywhere above that component.", "No; the controlling string must be at the component depth.", "No; the controlling string should be the production casing, because the component had to pass that before reaching the liner.", "Only if the liner is also the string present at the component depth, which is what makes the label unambiguous in a report."]'::jsonb, 0, 'The label names the segment that set the minimum, which may be far above the depth asked about.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'A summary output from an unfamiliar tool looks surprisingly favourable. What is the disciplined next step?', '["Rerun the tool with different inputs and compare.", "Accept it if the detailed rows have been validated, since a summary of validated rows cannot itself be wrong in any way.", "Reproduce the selection by hand from the detail the same tool printed.", "Report the detail instead of the summary, so that the reader can make the selection themselves and no error is possible."]'::jsonb, 2, 'If the two disagree you have found something; if they agree you have learned what the tool means.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Why does the engine name the controlling string rather than the depth of the restriction?', '["Because the depth is not known at that point.", "Because the depth of the restriction changes with the component being checked, whereas the string label is a fixed property.", "Because a string label is easier to read in a report than a depth, and the depth can always be looked up from the profile.", "Because naming the string points at where the problem is, which is often far above the component."]'::jsonb, 3, 'A component at two thousand five hundred metres can have its problem at twenty four hundred.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Which of the four volumes would you use to order packer fluid?', '["The annulus above the packer.", "The capacity of the completion string.", "The volume below the packer, since that is the part of the well in communication with the reservoir once the packer is set.", "The displacement of the string, which is the volume the string occupies and therefore the volume the fluid has to fill."]'::jsonb, 0, 'It is the largest of the four by a wide margin in the published well.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'A tool reports a volume with no warnings. What has that established, and what has it not?', '["That the volume has been independently verified.", "That the profile covered every interval, and nothing about whether the program is correct.", "That the string and the casing program are consistent with one another, since an inconsistency would produce a warning.", "That the integration used exact breakpoints rather than a grid, which is what the absence of a warning is reporting."]'::jsonb, 1, 'Warnings catch missing data. They do not catch incorrect data.'),
  ('completion', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'What single change would you make to a validation suite after reading this tier?', '["Increase the number of test cases in the suite.", "Tighten the comparison tolerance between the engine and the oracle, so that a selection difference cannot hide inside it.", "Require the oracle to compute every reported output, including the summaries.", "Add a test for each refusal path, since those are the parts of the engine that are exercised least often by the goldens."]'::jsonb, 2, 'If the oracle skips an output, that output is unverified however thorough the rest is.'),
  ('completion', 'intermediate', 'final', null, 1, 'A well has production casing to three thousand metres and a liner from twenty four hundred. A tool asks what casing is at two thousand five hundred. Why is that question badly posed?', '["Because two strings are present and only the innermost one constrains the completion.", "Because the depth quoted is a measured depth.", "Because the liner has not been cemented at that depth, so it cannot be treated as part of the casing program at all.", "Because the casing weight changes within the production string, so the answer depends on which section is being asked about."]'::jsonb, 0, 'Building the profile resolves that once, and every check downstream reads the resolved answer.'),
  ('completion', 'intermediate', 'final', null, 2, 'You build a profile and get ten rows from a program of two strings and three sections. What went wrong?', '["Nothing; ten rows is the correct answer.", "Adjacent identical intervals were not merged, so the row count is meaningless.", "The profile was cut at every component boundary of the completion string as well as at the casing section boundaries.", "The two strings were kept separate over the overlap instead of being resolved into a single innermost bore for that interval."]'::jsonb, 1, 'Merging makes a change in the profile mean a real change in the well.'),
  ('completion', 'intermediate', 'final', null, 3, 'A profile builder merges two rows that came from different strings but share a bore. What breaks?', '["The volume integration loses a breakpoint.", "The governing drift becomes non monotonic, because the merged row inherits the drift of whichever string was processed first.", "The label on a failed check becomes ambiguous about which string caused it.", "The row count no longer matches the number of sections in the program, which is the check used to validate the profile."]'::jsonb, 2, 'The merge tests both the bore and the label, deliberately.'),
  ('completion', 'intermediate', 'final', null, 4, 'A component lands at twenty three hundred metres in the published well and another at twenty five hundred. What differs about their checks?', '["Nothing; both are checked against the same bore.", "The deeper one is checked against a warn margin and the shallower one is not, because the margin applies only below a liner top.", "The deeper one is checked against the nominal bore and the shallower one against the drift of the string above it.", "The deeper one is checked against the liner and the shallower one against the casing."]'::jsonb, 3, 'The liner top is the single most consequential depth in the well for this check.'),
  ('completion', 'intermediate', 'final', null, 5, 'A clearance is reported as five millimetres. A colleague pictures five millimetres of gap on one side. What is wrong?', '["Nothing; the value is a radial clearance.", "The value is a difference of areas rather than of diameters, so it cannot be converted into a gap without knowing the bore.", "The value already accounts for eccentricity, so the gap on the low side is zero and the gap on the high side is five.", "The value is diametral, so a centred component has two and a half millimetres on each side."]'::jsonb, 3, 'And a component lying against the wall has none at all on one side.'),
  ('completion', 'intermediate', 'final', null, 6, 'A design review claims a component is fine because the bore at its setting depth is generous. What has been missed?', '["That the component has to pass everything above that depth to get there.", "That the bore quoted is nominal rather than a drift.", "That the component might be run on a separate trip, in which case the bores above it would indeed not have to be passed.", "That the bore at the setting depth is measured at the coupling, which is wider than the pipe body the component sits in."]'::jsonb, 0, 'The constraint on a component is a property of the path, not of the destination.'),
  ('completion', 'intermediate', 'final', null, 7, 'Two components of identical outside diameter come back with clearances differing by a factor of nine. What is the explanation?', '["One has been measured incorrectly.", "One is eccentric and the other is concentric, so the effective clearance of the first is much smaller than its nominal one.", "One stops above a liner top and the other stops below it.", "One is checked at its top depth and the other at its bottom depth, and the difference between the two is a liner section."]'::jsonb, 2, 'Nothing about the components explains it.'),
  ('completion', 'intermediate', 'final', null, 8, 'You raise the warn margin on a passing string until something warns. What have you measured?', '["The correct value of the margin for that well.", "How much slack the design actually has.", "The uncertainty in the drift of the casing, which the margin is intended to represent and which the sweep therefore recovers.", "The clearance of the loosest row, since that is the last row to warn as the margin is progressively increased."]'::jsonb, 1, 'It is the fastest way to understand a design, and the panel lets you do it directly.'),
  ('completion', 'intermediate', 'final', null, 9, 'A completion passes with a tightest row of under five millimetres. Is the design comfortable?', '["Yes, because every row passed the check.", "It cannot be judged without the warn margin, since a row is only comfortable relative to the margin that has been set for it.", "No; the tightest row is the design and everything else contributes nothing to the decision.", "Yes, provided the string is run into new casing, because the drift guarantee then applies in full to every joint in the well."]'::jsonb, 2, 'Reporting thirteen green rows hides exactly the thing the reader needs.'),
  ('completion', 'intermediate', 'final', null, 10, 'An oversized component passes at two thousand metres and fails at two thousand five hundred in the same well. Is the model wrong?', '["Yes; a component either fits a well or it does not.", "No; the component is identical and the path above it changed.", "Yes, unless the casing changes weight between the two depths, in which case the difference in bore explains the two results.", "No, but the failure should have been reported as a refusal, since a component that will not go is not a valid design input."]'::jsonb, 1, 'That is exactly what the check is for, and a failure is reported rather than refused.'),
  ('completion', 'intermediate', 'final', null, 11, 'A tool refuses a component whose bore exceeds its body. A colleague calls that unhelpful. What is the argument for it?', '["Refusals are required by the specification.", "Accepting it would produce a negative steel volume, which would propagate through the volume calculation and give a wrong total.", "The input describes no physical object, and both consequences of accepting it flatter the design.", "The two numbers are in the same units, so the tool cannot tell which of the two was intended and must therefore refuse both."]'::jsonb, 2, 'A smaller body clears easily and a larger bore improves the through bore, both in the wrong direction.'),
  ('completion', 'intermediate', 'final', null, 12, 'A wireline job needs to reach two thousand metres in the published string. Which bore limits it?', '["The no go nipple bore, which is the smallest in the string.", "The tubing bore, because the plain tubing makes up almost all of the string between surface and the depth in question.", "The packer bore, because a tool has to pass the packer to reach anything at all in the lower part of the completion.", "The safety valve bore, since the no go nipple is far below that depth."]'::jsonb, 3, 'The running form of the through bore answers what can reach a depth rather than only the bottom.'),
  ('completion', 'intermediate', 'final', null, 13, 'A completion is quoted with one bore figure and a client asks whether it is a restricted string. What do you supply?', '["Both the extreme and the extents, so the figure cannot be misread.", "The extreme alone, since that is the standard figure.", "The bore of every component in the string, so that the client can compute whatever summary they consider appropriate.", "The extent alone, since the fraction of the string that is restricted is what determines whether the string is restricted."]'::jsonb, 0, 'An extreme value summary is correct and can be badly misleading.'),
  ('completion', 'intermediate', 'final', null, 14, 'The no go nipple governs a few metres of a two and a half kilometre string. Should it be removed?', '["Yes, because it sets the advertised bore of the string.", "No; stopping a tool of the wrong size is what the component is for.", "Yes, unless a plug is planned, since the restriction costs access for the whole producing life for a single future operation.", "It depends on the extent, and a component governing less than one percent of a string should always be reconsidered."]'::jsonb, 1, 'A course that treated the smallest bore as a problem would have missed the point of the component causing it.'),
  ('completion', 'intermediate', 'final', null, 15, 'A client needs a larger tool through a completion. Which restriction is worth attacking?', '["The no go nipple, by opening out its bore.", "The tubing, since running a size larger raises every bore in the string and therefore removes both restrictions at once.", "The safety valve, since a larger bore valve exists at a larger outside diameter.", "The packer, whose bore in the published string equals the safety valve bore and is therefore equally restrictive."]'::jsonb, 2, 'That is a genuine trade between the two checks in this tier.'),
  ('completion', 'intermediate', 'final', null, 16, 'You are told the annulus above the packer is five times the string capacity. Does that sound right?', '["No; the annulus is a narrow gap and must be smaller.", "No; the two should be comparable, because the annular area and the tubing bore area are of similar magnitude in most wells.", "Only in a liner, where the reduced bore brings the annular area down to the same order as the capacity of the string.", "Yes; area goes as the square and the casing bore is much larger than the tubing outside diameter."]'::jsonb, 3, 'Over two and a half kilometres that adds up to a lot of packer fluid.'),
  ('completion', 'intermediate', 'final', null, 17, 'An annulus integral is written with breakpoints from the casing program only. What is missing?', '["The component boundaries, where the string outside area changes.", "The packer depth and the total depth.", "The depths at which the drift class of the casing changes, which is where the effective bore for the integral steps as well.", "Nothing, because the string outside area is constant along the completion and only the casing bore varies with depth."]'::jsonb, 0, 'A five and three quarter inch valve displaces more annulus than the tubing around it.'),
  ('completion', 'intermediate', 'final', null, 18, 'A calculation reports the below packer volume as an annular area. What has gone wrong?', '["Nothing; an annular area is correct below the packer.", "The tail is open and perforated, so the fluid inside and around it is one body.", "The packer depth has been confused with the total depth, so the calculation has integrated over the wrong depth interval.", "The perforated joint outside diameter has been used in place of the tubing outside diameter over the whole tail section."]'::jsonb, 1, 'Treating it as an annulus would exclude a volume that nothing physical excludes.'),
  ('completion', 'intermediate', 'final', null, 19, 'Two engineers get volumes differing in the fourth digit. One used a one metre grid. Who is right?', '["Whichever used the finer grid.", "Neither, since both methods approximate the same integral and the true value lies somewhere between the two results.", "The one who cut on breakpoints, because the integrand is piecewise constant and the sum is exact.", "The one who used the grid, because a grid captures the variation within a long casing section that breakpoints miss."]'::jsonb, 2, 'Any quadrature is at best equal to the exact sum and at worst wrong near the discontinuities.'),
  ('completion', 'intermediate', 'final', null, 20, 'When would you have to abandon exact summation for the volumes?', '["If the string had more than twenty components.", "If the well were deviated, because the annular area then depends on the inclination and cannot be treated as constant.", "If the packer fell exactly on a casing section boundary, which makes the breakpoint set degenerate and the sum ill defined.", "If an area varied continuously with depth, as with a real caliper log."]'::jsonb, 3, 'Then quadrature is the right tool and the step size is a genuine parameter to choose.'),
  ('completion', 'intermediate', 'final', null, 21, 'A volume comes back with a warning naming a two hundred metre interval. What do you do next?', '["Go back to the casing program and find the section that was not entered.", "Discard the volume and refuse to report it.", "Add the missing volume by assuming the bore of the section above the gap, which bounds the error to a few percent at most.", "Report the volume as computed, since the warning shows the engine has already handled the gap appropriately."]'::jsonb, 0, 'It is nearly always a section that was missed rather than a genuinely uncased interval.'),
  ('completion', 'intermediate', 'final', null, 22, 'A clearance check meets the same gap. Why does it return nothing rather than a partial verdict?', '["Because clearances cannot be computed without a bore.", "Because the missing interval could contain the restriction that fails.", "Because a verdict has to be reported for every component, and a partial list would be misread as a complete one by any reader.", "Because the engine cannot tell whether the gap is above or below the component being checked, so it declines to guess."]'::jsonb, 1, 'A pass over the intervals we know about is not a partial pass, it is a wrong answer.'),
  ('completion', 'intermediate', 'final', null, 23, 'A summary reports the worst clearance of a passing string as the first tubing joint. What has happened?', '["The selection ranked by status alone, so no row outranked the incumbent.", "The rows were computed in the wrong order.", "The first tubing joint genuinely is the tightest, because it is checked against the shallowest and therefore smallest casing.", "The warn margin was set to zero, which makes every row pass and forces the selection to fall back on the first row."]'::jsonb, 0, 'The reduction returned whatever it started with.'),
  ('completion', 'intermediate', 'final', null, 24, 'Why was that defect invisible on the cases where somebody was looking for a problem?', '["Because failing strings were never tested.", "Because the reduction was only reached when the string had more than one row, and failing strings were usually short ones.", "Because a failing row outranked the passing ones, so mixed strings reported correctly.", "Because a failing string produces a refusal rather than a summary, so the worst row is never reported for one at all."]'::jsonb, 2, 'It was present on exactly the cases where the report was being used as reassurance.'),
  ('completion', 'intermediate', 'final', null, 25, 'An oracle reproduces every clearance row exactly and the worst row is still wrong. Why?', '["Because the rows are data and the selection is logic, and the oracle computed no selection.", "Because the oracle used a different tolerance.", "Because the oracle computed the rows in a different order, so a selection that depends on order would not have matched anyway.", "Because the worst row is reported with extra fields that the oracle does not produce, so it was excluded from the comparison."]'::jsonb, 0, 'It was an output of the engine that no test read.'),
  ('completion', 'intermediate', 'final', null, 26, 'You are auditing a model. Which outputs would you check first, given this lesson?', '["The outputs with the most significant figures.", "The summaries: worst cases, controlling items, binding constraints, recommended values.", "The outputs that appear in the fewest test cases, since coverage is the best available proxy for the risk of a defect.", "The outputs that depend on the largest number of inputs, since those have the most opportunities to be computed wrongly."]'::jsonb, 1, 'They get read by every user and tested by nobody.'),
  ('completion', 'intermediate', 'final', null, 27, 'State what the corrected worst row selection does on a string where every row passes.', '["It returns the first row, as before.", "It returns nothing, because a worst row is only defined when at least one row has a status worse than the others.", "It returns the tightest passing row.", "It returns the row with the largest outside diameter, which on a uniform string is the one most likely to be the tightest."]'::jsonb, 2, 'That is what the reader wanted all along.'),
  ('completion', 'intermediate', 'final', null, 28, 'Why does the guard assert a ratio rather than only the identity of the selected row?', '["Because the row identity might legitimately change.", "Because the ratio is easier to compute in a test than the row identity, which requires the whole list to be searched first.", "Because the ratio is independent of the warn margin, whereas the identity of the selected row depends on where it is set.", "Because a degenerate selection on that string gives exactly that ratio, so the assertion is aimed at the failure mode."]'::jsonb, 3, 'Two guards are better than one, and one of them should be aimed at the specific way it broke.'),
  ('completion', 'intermediate', 'final', null, 29, 'A row could not be evaluated because the profile has a gap. Should it be selected as the worst?', '["No; a row we could not evaluate is not evidence of tightness.", "Yes, because an unknown is the worst case.", "Yes, but only if no other row in the string has a failing status, since a real failure always outranks an unknown one.", "It depends on whether the gap is above or below the row, since only a gap above it affects the clearance calculation."]'::jsonb, 0, 'The corrected ranking never selects it over a row that has a value.'),
  ('completion', 'intermediate', 'final', null, 30, 'A deviated well is completed with a string that passes every geometric check. What has not been established?', '["That the components clear the casing above them.", "That the string can actually be pushed to depth.", "That the through bore is large enough for the tools the well will need over its producing life, which the check does not cover.", "That the volumes are correct, since the volume integration assumes a vertical well and no correction has been applied."]'::jsonb, 1, 'A completion that fits perfectly can be undeliverable.'),
  ('completion', 'intermediate', 'final', null, 31, 'A three metre packer passes a straight hole check. What extra consideration applies in a dogleg?', '["None; a packer is short enough to be unaffected.", "The clearance has to be recomputed against the inside of the bend, where the effective bore is smaller than the nominal one.", "A rigid component needs more room, growing with its length and the curvature.", "The packer has to be checked against the casing at both ends of the dogleg rather than at its own setting depth alone."]'::jsonb, 2, 'The clearance check treats each component as a point at a depth, and there is no survey in it.'),
  ('completion', 'intermediate', 'final', null, 32, 'What is the strongest claim the Professional tier makes?', '["That the completion will work in the well.", "That the completion can be run, will produce and is correctly rated, provided the casing program supplied is accurate.", "That every result has been validated against an independent oracle, including the summaries the engine reports.", "That the geometry is right, exactly, on the data given."]'::jsonb, 3, 'A narrow claim that is strongly supported is worth more than a wide one that is approximately supported.'),
  ('completion', 'intermediate', 'final', null, 33, 'A drift run comes back tighter than the casing program predicts. What does that tell you about the clearance report?', '["That the reported clearances were against the best case and the real ones are smaller.", "That the casing program was entered incorrectly.", "That the warn margin was set too high, since the margin was intended to cover exactly the difference the drift run has revealed.", "That the drift run tool was undersized, because a drift run cannot report a bore smaller than the mill guarantee for new pipe."]'::jsonb, 0, 'The catalog value says what to expect and the drift run says what is there.'),
  ('completion', 'intermediate', 'final', null, 34, 'Two designs for the same well differ only in where the side pocket mandrel sits. How do you compare them?', '["On the total string length of each.", "On the mandrel clearance in each, against the operational value of the injection depth.", "On the through bore of each, since moving a component changes which restriction governs and therefore the advertised bore.", "On the annulus volume of each, because the mandrel body displaces annulus and moving it changes how much fluid is needed."]'::jsonb, 1, 'The trade is a much larger clearance against a higher gas lift injection point.'),
  ('completion', 'intermediate', 'final', null, 35, 'A component list is checked against a profile with a gap below the deepest component. What happens?', '["Every verdict comes back as unknown.", "The deepest component is reported as unknown and the rest are reported normally, since only that one is adjacent to the gap.", "Nothing; the gap is below everything being checked and affects no verdict.", "The volume calculation refuses, because it integrates to total depth and the gap falls inside the range it has to cover."]'::jsonb, 2, 'The governing drift is a minimum over what is above, so a gap below is irrelevant to it.'),
  ('completion', 'intermediate', 'final', null, 36, 'You want one number that tells a reader how much room a completion design has. Which do you give?', '["The average clearance across all the rows.", "The number of rows that pass, warn and fail, which summarises the whole check in three integers rather than in one number.", "The ratio of the loosest row to the tightest, which describes the spread and therefore how concentrated the risk is.", "The tightest clearance, with the component and the controlling string named."]'::jsonb, 3, 'The tightest row is the design; the ratio is context for it.'),
  ('completion', 'intermediate', 'final', null, 37, 'The exposed profile of a well has three rows and the program has two strings. Is that consistent?', '["Yes, if one string has two sections of different weight above the other string''s top.", "No; the profile must have one row per string.", "No; the profile must have one row per section in the program, which for two strings and three sections would be three rows.", "Only if the two strings do not overlap, since an overlap always produces an extra row where both are present at once."]'::jsonb, 0, 'The published well is exactly that case.'),
  ('completion', 'intermediate', 'final', null, 38, 'Which of these would change the governing drift at a depth without changing anything at that depth?', '["Changing the casing weight at that depth.", "Adding a tighter string anywhere above it.", "Increasing the warn margin used by the clearance check, since the margin is subtracted from the drift before the comparison.", "Moving the packer, which changes which components are checked against the drift at that depth but not the drift itself."]'::jsonb, 1, 'The governing drift is a running minimum from surface, so anything above it can set it.'),
  ('completion', 'intermediate', 'final', null, 39, 'A tool prints the governing drift falling and then rising with depth. What do you conclude?', '["The well has a tie back inside the liner.", "The profile has a gap, and the tool has filled it with the bore of the section below rather than returning nothing for it.", "The implementation is wrong, because a running minimum cannot rise.", "The casing weight decreases with depth in that well, which is unusual but legitimate and produces exactly that shape."]'::jsonb, 2, 'A curve that stepped up would mean a restriction had been un passed.'),
  ('completion', 'intermediate', 'final', null, 40, 'A reviewer asks why the clearance check does not simply use the bore at each component depth. What is the shortest answer?', '["Because the bore at a depth is not always known.", "Because the bore at a depth is a nominal figure, whereas the check needs the drift, which is only published per string.", "Because the components are placed by the tally rather than by design, so their exact depths are not known until the string is run.", "Because a component has to pass everything above it to get there."]'::jsonb, 3, 'It is the single most important idea in the tier, and it is easy to state and easy to forget.'),
  ('completion', 'intermediate', 'final', null, 41, 'You have to explain the difference between the two fit checks in one sentence. What do you say?', '["One is outside diameters against casing bores; the other is inside diameters against each other.", "One is computed before running and one afterwards.", "One uses the drift of the casing and the other uses the nominal bore, which is why the two give different answers for the same string.", "One is a minimum over the string and the other is a sum over it, which is why one is reported per row and the other as a total."]'::jsonb, 0, 'Getting down and getting through are genuinely different questions with different answers.'),
  ('completion', 'intermediate', 'final', null, 42, 'A completion report gives thirteen clearances, a through bore and four volumes, and no warnings. What is still unstated?', '["The total length of the completion string.", "Whether the casing program used was the as built one, which is the only thing a report of that kind cannot establish for itself.", "How much of the string the through bore restriction governs, and which row is the tightest.", "The warn margin that was applied, without which none of the thirteen clearance verdicts can be interpreted by any reader."]'::jsonb, 2, 'Both summaries need their context, and a clean report is where that is easiest to forget.');
